"""Frame objects."""

import abc
import dataclasses
import enum
import struct
import typing

from jsilib import _utils
from jsilib.aio import helpers
from jsilib.aio.interface import IStreamReader, IStreamWriter

from . import exc

__all__ = export = _utils.ExportList()

_JSI_PREAMBLE = b'JSI'
_JSI_VERSION = (2, 0)


@dataclasses.dataclass
class _RangeValidator:
    min: int
    max: int

    def __call__(self, frame: 'Frame', name: str):
        value = getattr(frame, name)
        if not (self.min <= value <= self.max):
            raise ValueError(f'{name!r} is out of range: {value} not in [{self.min}, {self.max}]')


@dataclasses.dataclass
class _MaxLengthValidator:
    max: int

    def __call__(self, frame: 'Frame', name: str):
        value = getattr(frame, name)
        if len(value) > self.max:
            raise ValueError(f'{name!r} is too long: {len(value)} (given) > {self.max} (maximal)')


@export
@dataclasses.dataclass(frozen=True)
class Frame(abc.ABC):
    """Base class for frames."""

    class Type(enum.Enum):
        """Enumeration with supported frame types."""
        CHUNK = 1
        TERM = 2
        PING = 3
        PONG = 30
        ACK = 100
        NACK = 200

    __header_fmt = struct.Struct('!3sBB')  # MAGIC_BYTES(3) | Version(1) | Type(1)

    _validators = {}

    def __post_init__(self):
        for name, validate in self._validators.items():
            validate(self, name)

    @property
    @abc.abstractmethod
    def type(self) -> Type:
        """The type of this frame."""

    @abc.abstractmethod
    async def dump(self, stream: IStreamWriter):
        """Dump this frame into binary payload and write to given *stream*."""
        version_major, version_minor = _JSI_VERSION
        version = (version_major << 4) | version_minor
        await helpers.write_all(stream, self.__header_fmt.pack(_JSI_PREAMBLE, version, self.type.value))

    @classmethod
    async def load(cls, stream: IStreamReader) -> 'Frame':
        """Decode frame from given *stream*.

        On success, :class:`Frame` object is returned (use :attr:`Frame.type`
        or :func:`isinstance` to check the actual type). On failure,
        :exc:`FrameDecodeError` is raised.
        """
        raw_header = await helpers.read_all(stream, cls.__header_fmt.size)
        preamble, version, type = cls.__header_fmt.unpack(raw_header)
        if preamble != _JSI_PREAMBLE:
            raise exc.FrameDecodeError(f'invalid preamble: {preamble!r}')
        major, minor = version >> 4, version & 0xf
        if (major, minor) != _JSI_VERSION:
            raise exc.FrameDecodeError(f'unsupported frame version: {major}.{minor}')
        if type == cls.Type.CHUNK.value:
            return await Chunk._load_rest(stream)
        if type == cls.Type.ACK.value:
            return await Ack._load_rest(stream)
        if type == cls.Type.NACK.value:
            return await Nack._load_rest(stream)
        if type == cls.Type.TERM.value:
            return await Term._load_rest(stream)
        if type == cls.Type.PING.value:
            return await Ping._load_rest(stream)
        if type == cls.Type.PONG.value:
            return await Pong._load_rest(stream)
        raise exc.FrameDecodeError(f'unsupported frame type: {type}')


@export
@dataclasses.dataclass(frozen=True)
class Term(Frame):
    """Represents TERM frame.

    This frame is used to signal to the other side of a connection that no more
    frames will be sent. And once peer receives it, it should also send TERM
    frame to inform that it accepted it. The whole transaction is used to
    achieve a graceful connection shutdown.
    """

    @property
    def type(self) -> Frame.Type:
        return Frame.Type.TERM

    async def dump(self, stream: IStreamWriter):
        return await super().dump(stream)

    @classmethod
    async def _load_rest(cls, stream: IStreamReader) -> 'Term':
        return cls()


@dataclasses.dataclass(frozen=True)
class _PingPongBase(Frame):
    ping_id: int

    __header_fmt = struct.Struct('!I')  # Ping_ID(4)

    _validators = dict(Frame._validators)
    _validators.update({'ping_id': _RangeValidator(0, 2**32 - 1)})

    async def dump(self, stream: IStreamWriter):
        await super().dump(stream)
        await helpers.write_all(stream, self.__header_fmt.pack(self.ping_id))

    @classmethod
    async def _load_ping_id(cls, stream: IStreamReader) -> int:
        raw_header = await helpers.read_all(stream, cls.__header_fmt.size)
        ping_id, = cls.__header_fmt.unpack(raw_header)
        return ping_id


@export
class Ping(_PingPongBase):
    """Represents PING frame.

    This is used to keep the connection between two peers alive. Once peer
    receives a PING frame, it should reply with a PONG frame as soon as
    possible (i.e. with highest priority). PING frames can be sent by both
    sides of the connection simultaneously (so each peer can ping the other).

    :attr ping_id:
        The ID to be later sent back with corresponding PONG frame.
    """

    @property
    def type(self) -> Frame.Type:
        return Frame.Type.PING

    @classmethod
    async def _load_rest(cls, stream: IStreamReader) -> 'Ping':
        return cls(await cls._load_ping_id(stream))


@export
class Pong(_PingPongBase):
    """Represents PONG frame.

    This frame is used to create response for incoming PING frame. See
    :class:`Ping` for more details.

    :attr ping_id:
        The ID from received PING frame.
    """

    @property
    def type(self) -> Frame.Type:
        return Frame.Type.PONG

    @classmethod
    async def _load_rest(cls, stream: IStreamReader) -> 'Pong':
        return cls(await cls._load_ping_id(stream))


@dataclasses.dataclass(frozen=True)
class _DataTransferBase(Frame):
    message_id: int
    index: int

    __header_fmt = struct.Struct('!IH')  # Message_ID(4) | Index(2)

    _validators = dict(Frame._validators)
    _validators.update({
        'message_id': _RangeValidator(0, 2**32 - 1),
        'index': _RangeValidator(0, 2**16 - 1),
    })

    @dataclasses.dataclass
    class Key:
        message_id: int
        index: int

    @property
    def key(self) -> Key:
        return self.Key(self.message_id, self.index)

    async def dump(self, stream: IStreamWriter):
        await super().dump(stream)
        await helpers.write_all(stream, self.__header_fmt.pack(self.message_id, self.index))

    @classmethod
    async def _load_message_id_and_index(cls, stream: IStreamReader) -> typing.Tuple[int, int]:
        raw_header = await helpers.read_all(stream, cls.__header_fmt.size)
        message_id, index = cls.__header_fmt.unpack(raw_header)
        return message_id, index


@export
@dataclasses.dataclass(frozen=True)
class Chunk(_DataTransferBase):
    """Represents CHUNK frame.

    Chunk frames are used to transfer binary data between peers. Once peer
    receives a CHUNK frame it should dispatch it to the stream that is
    currently being read and represents message as a whole. If whole CHUNK
    payload is read, then stream reader must await for another CHUNK (i.e. read
    will block). And from the sender PoV no more chunks are allowed to be sent
    before previous one is either ACKed or NACKed (which is done by reading
    side once entire payload from current chunk was read).

    :param message_id:
        The ID of a binary message.

        Every chunk belonging to same message must have same message ID
        assigned. Chunks with different message IDs are treated as a separate
        messages. Thanks to this, multiple messages can be sent simultaneously
        over a single connection.

    :param index:
        The index of this chunk.

        Identifies chunk within same message ID. Must be used to construct ACK
        or NACK response for this chunk. Moreover, subsequent chunks must use
        consecutive indices, starting from 0 (i.e. 0, 1, 2 and so on).

    :param message_size:
        The size of a whole message.

        This can be used to calculate how many bytes are awaiting to be read,
        which means that this can be used to determine if the peer should wait
        for another CHUNK or not.

    :param payload:
        Binary payload sent inside this chunk.
    """
    message_size: int
    payload: bytes

    __header_fmt = struct.Struct('!BIBH')  # Message_Size(5) | len(Payload)(3)

    _validators = dict(_DataTransferBase._validators)
    _validators.update({
        'message_size': _RangeValidator(0, 2**40 - 1),
        'payload': _MaxLengthValidator(2**24 - 1),
    })

    def __repr__(self):
        return f"{self.__class__.__qualname__}("\
            f"message_id={self.message_id}, "\
            f"index={self.index}, "\
            f"message_size={self.message_size}, "\
            f"payload={_utils.format_binary_payload(self.payload, prefix_length=16, postfix_length=8)})"

    @property
    def type(self) -> Frame.Type:
        return Frame.Type.CHUNK

    async def dump(self, stream: IStreamWriter):
        await super().dump(stream)
        message_size = self.message_size & 0xffffffffff
        message_size_hi, message_size_lo = message_size >> 32, message_size & 0xffffffff
        payload_size = len(self.payload) & 0xffffff
        payload_size_hi, payload_size_lo = payload_size >> 16, payload_size & 0xffff
        await helpers.write_all(
            stream, self.__header_fmt.pack(message_size_hi, message_size_lo, payload_size_hi, payload_size_lo)
        )
        await helpers.write_all(stream, self.payload)

    @classmethod
    async def _load_rest(cls, stream: IStreamReader) -> 'Chunk':
        message_id, index = await cls._load_message_id_and_index(stream)
        raw_header = await helpers.read_all(stream, cls.__header_fmt.size)
        message_size_hi, message_size_lo, payload_size_hi, payload_size_lo = cls.__header_fmt.unpack(raw_header)
        message_size = (message_size_hi << 32) | message_size_lo
        payload_size = (payload_size_hi << 16) | payload_size_lo
        payload = await helpers.read_all(stream, payload_size)
        return cls(message_id, index, message_size, payload)


@export
class Ack(_DataTransferBase):
    """Represents ACK frame.

    It is used by CHUNK receiver to indicate that chunk was received and the
    sender can send another CHUNK (if any). Since this is equivalent to
    requesting of a next chunk, the receiver can decide when to ask for another
    chunk (and it does so when it has fully processed payload coming with
    current CHUNK).

    :param message_id:
        The ID of a message (from CHUNK frame to be ACKed).

    :param index:
        The index of a chunk to ACK (from CHUNK frame to be ACKed).
    """

    @property
    def type(self) -> Frame.Type:
        return Frame.Type.ACK

    @classmethod
    async def _load_rest(cls, stream: IStreamReader) -> 'Ack':
        message_id, index = await cls._load_message_id_and_index(stream)
        return cls(message_id, index)

    @classmethod
    def from_chunk(cls, chunk: Chunk) -> 'Ack':
        """Create ACK frame for corresponding CHUNK frame."""
        return cls(chunk.message_id, chunk.index)


@export
@dataclasses.dataclass(frozen=True)
class Nack(_DataTransferBase):
    """Represents NACK frame.

    It is used by CHUNK receiver to indicate that it has received chunk but is
    no longer interested in receiving more chunks from given message. This may
    happen f.e. when stream representing message that is being sent is closed.

    :param message_id:
        The ID of a message (from CHUNK frame to be ACKed).

    :param index:
        The index of a chunk to ACK (from CHUNK frame to be ACKed).

    :param reason:
        Placeholder for NACK reason.

        This is meant to be used for a short explanation of why message
        transfer was terminated.
    """
    reason: bytes

    __header_fmt = struct.Struct('!B')  # len(reason)(1)

    _validators = dict(_DataTransferBase._validators)
    _validators.update({
        'reason': _MaxLengthValidator(2**8 - 1),
    })

    @property
    def type(self) -> Frame.Type:
        return Frame.Type.NACK

    async def dump(self, stream: IStreamWriter):
        await super().dump(stream)
        await helpers.write_all(stream, self.__header_fmt.pack(len(self.reason)))
        await helpers.write_all(stream, self.reason)

    @classmethod
    async def _load_rest(cls, stream: IStreamReader) -> 'Nack':
        message_id, index = await cls._load_message_id_and_index(stream)
        raw_header = await helpers.read_all(stream, cls.__header_fmt.size)
        reason_size, = cls.__header_fmt.unpack(raw_header)
        reason = await helpers.read_all(stream, reason_size)
        return cls(message_id, index, reason)

    @classmethod
    def from_chunk(cls, chunk: Chunk, reason: bytes) -> "Nack":
        """Create NACK frame for given *chunk*."""
        return cls(message_id=chunk.message_id, index=chunk.index, reason=reason)
